INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (101, '4.7.0', 'Foundation Lock & Production Stabilization', '2026-08-27 07:50:24.492201+00', 'V4.7 upgrade started from confirmed V4.6 migration 100 baseline.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (102, '4.7.0', 'Foundation Lock & Production Stabilization', '2026-08-27 07:51:02.474954+00', 'Strict automatic accounting posting and new-tenant accounting provisioning.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (103, '4.7.0', 'Foundation Lock & Production Stabilization', '2026-08-27 07:51:21.600834+00', 'Request-id idempotency foundation; retry-safe sales and purchases.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (104, '4.7.0', 'Foundation Lock & Production Stabilization', '2026-08-27 07:51:41.47795+00', 'Retry-safe wrappers for expenses, payments, returns, stock adjustments/transfers and shift open/close.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (105, '4.7.0', 'Foundation Lock & Production Stabilization', '2026-08-27 07:52:12.387494+00', 'Separate physical installation history and atomic activation claim while preserving V4.6 system IDs.');
