INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (191, '4.9.0', 'Loan Collection Hardening', '2026-08-29 19:36:13.293853+00', 'Repairs accounting mappings, separates Client devices from POS cash drawer behavior and hardens loan payment posting.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (192, '4.9.0', 'Party Payment Center', '2026-08-29 19:36:13.293853+00', 'Pending Payments is grouped by customer/supplier with sales, loans, legacy purchases, Purchasing V2 invoices, credits and payment drill-down.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (193, '4.9.0', 'Payments & Collections Hardening', '2026-08-29 19:36:13.293853+00', 'Build 21 hardens loan collection, separates Client devices from POS cash drawers, improves light-theme text contrast, and redesigns Pending Payments around customer/supplier balances with drill-down.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (194, '4.9.1', 'Return Accounting Repair', '2026-08-29 21:08:25.020279+00', 'Self-heals return and loan accounting mappings and repairs Sales/Purchase Return journal posting for existing tenants.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (195, '4.9.1', 'Bidirectional Loans', '2026-08-29 21:14:14.650483+00', 'Adds Loans Given and Loans Taken, lender/borrower counterparties, loan payable/interest expense accounting and a business-level loan accounting switch.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (196, '4.9.1', 'Finance Reconciliation', '2026-08-29 21:14:14.650483+00', 'Cross-checks double-entry balance, duplicate source journals, accounting mappings, Sales/Purchase/Purchase Invoice/Expense/Return/Loan journal coverage and overpayments.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (197, '4.9.1', 'Financial Integrity & Bidirectional Loans', '2026-08-29 21:14:14.650483+00', 'Sales-return accounting repair, loans given/taken, module accounting switch, finance reconciliation, party payment integration and compact Client workspace UI.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (198, '4.9.5', 'Invoice & Print Foundation', '2026-08-29 22:19:53.818908+00', 'Tenant logo assets, selectable invoice columns, richer A4 template defaults and print/export capability metadata.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (199, '4.9.5', 'Tasks & Notifications', '2026-08-29 22:22:25.389086+00', 'Task reminders, notification-to-task conversion, customer/supplier due alerts, approvals and synchronized task status notifications.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (200, '4.9.5', 'Search & Output API', '2026-08-29 22:22:38.463238+00', 'Starts-with ranked selector search for products/parties/accounts/locations plus common print/download output auditing.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (201, '4.9.5', 'Invoices, Workflow, Output & Search', '2026-08-29 22:22:49.286408+00', 'Invoice branding and selectable columns, printer/PDF/export infrastructure, synchronized task notifications and starts-with searchable selectors.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (202, '5.0.0', 'Finance Controls & Journal Center', '2026-08-30 08:49:14.911571+00', 'Financial years, payment/receipt/contra vouchers, bank accounts/reconciliation, recurring expenses and safe journal detail/reversal controls.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (203, '5.0.0', 'CRM & Purchasing Intelligence', '2026-08-30 08:49:14.911571+00', 'Customer groups/CRM/loyalty, supplier quotation comparison and conversion, supplier performance and smart reorder recommendations.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (204, '5.0.0', 'THQ Reports Center', '2026-08-30 08:49:14.911571+00', 'Central report catalogue, detailed Sales/Purchase Returns data and unified report data endpoints for accounting, inventory, purchasing and sales.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (205, '5.0.0', 'Notification & Task Center', '2026-08-30 08:49:14.911571+00', 'Fixes task citext runtime mismatch and adds task history/comments/escalation plus inventory, sync, recurring-expense and task escalation notifications.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (206, '5.0.0', 'Milestone Financial Reconciliation', '2026-08-30 08:49:14.911571+00', 'Extends finance diagnostics with operational-vs-GL AR/AP and bidirectional loan balances plus journal integrity checks.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (207, '5.0.0', 'Dashboard & Business Intelligence', '2026-08-30 08:52:03.530842+00', 'Return-aware sales/profit, dues, stock risk, best sellers, store comparison and hourly trends.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (208, '5.0.0', 'Platform Completion', '2026-08-30 08:52:03.530842+00', 'Capability contract for v5 milestone workspaces and cross-module controls.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (209, '5.0.0', 'Milestone Verification', '2026-08-30 08:52:03.530842+00', 'Database contract verifier for finance, CRM, purchasing intelligence, reports, tasks/notifications and BI.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (210, '5.0.0', 'THQ ERP 5 Milestone', '2026-08-30 08:52:03.530842+00', 'Build 24 milestone release contract. Finance, CRM, intelligent purchasing, reports, notifications/tasks, BI and reconciliation.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (211, '5.0.0', 'Build 25 Audit Repairs', '2026-08-30 11:24:49.76488+00', 'Audit-driven v5 completion: period locks/opening/closing, journal safety, bank reconciliation, CRM pricing validation, purchasing validation, approved stock adjustments, task security, BI, reports and reconciliation hardening.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (212, '5.0.0', 'Admin POS & Store Creation Hotfix', '2026-08-30 12:18:01.446642+00', 'Automatic permanent POS prefixes, repaired POS creation audit path, canonical MAIN location creation, and child-store parent enforcement.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (213, '5.1.0', 'Warranty & Transport Service', '2026-08-30 19:59:32.012849+00', 'Repairs serial/batch/warranty lookup compatibility, warranty synchronization, and completes validated Transport/Service vehicle-job-billing lifecycle.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (214, '5.2.0-foundation', 'GST & Compliance Foundation', '2026-08-30 21:20:21.649139+00', 'Normalized GST masters/registrations/party/product profiles, centralized GST quote engine, compliance permissions/navigation, setup diagnostics and offline POS tax/cache hardening. No GSP/IRP production integration yet.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (215, '5.2.0-foundation', 'GST Foundation Hotfix 1', '2026-08-30 21:22:33.229904+00', 'Repairs GST quote PL/pgSQL variable/column ambiguity discovered by rollback calculation matrix.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (216, '5.2.0-foundation', 'GST Foundation Hotfix 2', '2026-08-30 21:23:38.056289+00', 'Separates zero-rated supply classification from with-payment/without-payment tax treatment for SEZ and exports.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (217, '5.2.0-foundation', 'GST Foundation Hotfix 3', '2026-08-30 21:24:45.606313+00', 'Makes product tax profile changes safely effective-dated: same-day replacement in place and historical periods retained for prior-document reproducibility.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (218, '5.2.0-foundation', 'GST Master & Rule Corrections', '2026-08-30 21:35:22.334066+00', 'Corrects local SGST/UTGST jurisdiction metadata and E-Way Bill 180/360-day policy effective dates after foundation audit.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (219, '5.2.0-foundation', 'GST Configuration History Safety', '2026-08-30 21:39:23.28903+00', 'Effective-dated registration configuration versions, party GST profiles, and location-to-GSTIN assignments; GSTIN/PAN/state identity made immutable per registration.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (220, '5.2.0-foundation', 'Central GST Document Engine', '2026-08-30 21:44:04.991574+00', 'Adds one provider-neutral sale/purchase GST calculation and validation engine with correct SGST/UTGST routing, zero-rated handling, composition Bill of Supply behavior, separate reverse-charge liability, inclusive/fixed-cess math, strict party/product readiness, and backward-compatible sales/purchase wrappers.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (221, '5.2.0-foundation', 'Central GST Engine Hotfix 1', '2026-08-30 21:46:14.059957+00', 'Fixes PL/pgSQL party_type variable/column ambiguity found by rollback GST matrix testing. No business transaction data changed.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (222, '5.2.0-foundation', 'Central GST Engine Hotfix 2', '2026-08-30 21:47:37.718287+00', 'Fixes PL/pgSQL rate variable/column ambiguity found by rollback GST matrix testing. No business transaction data changed.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (223, '5.2.0-foundation', 'Central GST Engine Hotfix 3', '2026-08-30 21:48:57.97152+00', 'Reconciles tax-inclusive extraction/component rounding by summing finalized line totals and exposing calculation_rounding explicitly. No business transaction data changed.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (227, '5.2.0-foundation', 'GST Component Account Hierarchy', '2026-08-30 22:15:21.51603+00', 'Keeps v5.1 generic Input/Output GST as historical controls; adds component CGST/SGST/UTGST/IGST/Cess accounts plus separate RCM payable and deferred RCM input account families, with future-tenant bootstrap and deterministic mappings.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (228, '5.2.0-foundation', 'GST-Aware Accounting Aggregation', '2026-08-30 22:15:56.202461+00', 'Extends GST register and finance reconciliation so legacy generic GST postings and future component postings coexist without double counting. RCM payable and RCM input remain separate control families.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (229, '5.2.0-foundation', 'GST Accounting Control & Health', '2026-08-30 22:16:20.2793+00', 'Adds GST component control balances and integrity checks for missing mappings, legacy+component double posting, RCM parent/component mixing and component journals without authoritative GST snapshots.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (224, '5.2.0-foundation', 'Immutable GST Evidence Schema', '2026-08-30 22:03:36.058029+00', 'Creates immutable authoritative GST header/line snapshot storage and legacy-unverified marker storage. No historical tax components are inferred.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (225, '5.2.0-foundation', 'Controlled GST Evidence Writer', '2026-08-30 22:04:18.125409+00', 'Adds the internal authoritative snapshot writer with source binding, deterministic SHA-256 fingerprinting, idempotency and source-line linkage. No transaction posting behavior changes.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (226, '5.2.0-foundation', 'Legacy GST Evidence Markers', '2026-08-30 22:04:45.813355+00', 'Adds immutable legacy-unverified markers/backfill helpers and the permissioned evidence reader. Historical CGST/SGST/UTGST/IGST/Cess/RCM components are never fabricated.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (230, '5.2.0-foundation', 'GST Migration Contract Cleanup', '2026-08-30 22:26:43.717487+00', 'Removes redundant development-only GST writer/legacy helper overloads and retains the stricter canonical source-bound authoritative snapshot contract and legacy evidence/tamper contract from migrations 225-226.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (231, '5.2.0-foundation', 'GST RCM Liability Scope', '2026-08-30 22:31:36.840239+00', 'Separates outward recipient RCM from inward THQ RCM liability in the central GST engine, annotates line liability party, adds THQ/recipient RCM totals, and requires a normalized registered recipient for outward RCM.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (232, '5.2.0-foundation', 'GST Snapshot Journal Mapper', '2026-08-30 22:35:28.669701+00', 'Adds the canonical authoritative-snapshot to GST component journal-line mapper. Outward collected GST maps to Output components; inward supplier GST maps to Input components; inward RCM maps to separate pending-input and RCM-payable components; outward recipient RCM never posts as THQ liability. No business journal is posted by this migration.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (233, '5.2.0-foundation', 'GST Document Journal Composer', '2026-08-30 22:39:33.839537+00', 'Adds a non-posting, source-bound journal composer/validator for Sale, Purchase, Purchasing V2 Purchase Invoice, Sales Return and Purchase Return. It combines authoritative GST component lines with AR/AP/payments/revenue/inventory/direct-expense/COGS and explicit calculation+document rounding, and refuses generic GST control lines or unclassified additional charges.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (234, '5.2.0-foundation', 'Authoritative GST Journal Poster', '2026-08-30 22:43:03.14417+00', 'Adds the private guarded component-journal poster. It requires immutable authoritative GST evidence, refuses legacy evidence, serializes by source, verifies exact aggregated journal lines, rejects generic Input/Output GST controls and makes matching retries idempotent. No app endpoint is switched.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (235, '5.2.0-foundation', 'GST Transition Legacy Auto Evidence', '2026-08-31 04:01:27.083864+00', 'Automatically creates immutable legacy_unverified GST evidence for finalized v5.1 Sales/Purchases/Returns/Purchasing V2 invoices while v5.2 is under construction. Guarded authoritative context skips legacy marking for future v5.2 atomic writers.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (236, '5.2.0-foundation', 'GST Authoritative Transaction Context', '2026-08-31 04:05:48.536907+00', 'Adds a private transaction-ID/tenant/source scoped authoritative context. Only matching v5.2 atomic work suppresses the legacy generic origin journal and legacy marker; actor sync and cash drawer behavior remain unchanged. Normal v5.1 posting is untouched.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (237, '5.2.0-foundation', 'GST Operational Calculation Permission', '2026-08-31 04:10:24.222986+00', 'Adds least-privilege gst_compliance.calculate for operational roles, seeds current roles, auto-grants it for future roles/module enablement, and allows only the central GST quote engine to accept calculate-or-view access. Higher GST workspace/configuration/reconciliation/submission/cancellation permissions remain separate.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (238, '5.2.0-foundation', 'GST Legacy Accounting Guard', '2026-08-31 04:11:09.703583+00', 'Adds a private authoritative-context guard to the legacy v4 document accounting poster. Both origin-trigger and explicit wrapper calls remain normal for v5.1, but return without generic Input/Output GST posting while a matching v5.2 atomic Sale/Purchase is being assembled.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (239, '5.2.0-foundation', 'GST Legal Document Identity', '2026-08-31 04:13:49.688318+00', 'Separates internal THQ source_number from the legal GST document_number, derives legal numbers server-side from terminal/location invoice numbering or supplier invoice references, binds them to an immutable SHA-256 identity hash, and enforces outward document-number uniqueness per GST registration.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (240, '5.2.0-foundation', 'GST Atomic Request Contract', '2026-08-31 04:14:32.280996+00', 'Adds private SHA-256 request-payload idempotency for v5.2 atomic GST transactions. Same request+same payload returns the same evidence; same request with changed payload/operation is rejected. Completed requests are bound to source, immutable snapshot and journal IDs.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (241, '5.2.0-foundation', 'Atomic Authoritative GST Sale', '2026-08-31 04:20:50.04948+00', 'Adds the first v5.2 atomic Sale endpoint. It reuses THQ pricing, unit normalization, stock, serial/batch/warranty, origin/invoice numbering and cash-drawer paths, but central GST is the only tax calculator. The Sale, immutable GST evidence and component journal are committed as one transaction with strong request-payload idempotency; legacy generic GST posting/evidence is suppressed only inside the private authoritative context. Real additional charges remain blocked until charge-level GST classification exists.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (242, '5.2.0-foundation', 'Atomic Authoritative GST Purchase', '2026-08-31 05:49:33.019981+00', 'Adds the v5.2 atomic inventory Purchase endpoint. The Purchase source, immutable GST snapshot, component journal, supplier payable/payment split, RCM liability and inventory costing commit as one transaction. Central GST is the only tax calculator; recoverable supplier GST is excluded from inventory cost, line discounts reduce inventory basis, and RCM tax remains a THQ liability/pending-input component rather than supplier payable. Legacy generic accounting/evidence remains untouched for v5.1 and is suppressed only inside the private matching authoritative transaction context. Additional charges and service purchases remain blocked until their dedicated GST-classified source paths are introduced.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (243, '5.2.0-foundation', 'Atomic Authoritative GST Purchasing V2 Invoice', '2026-08-31 06:00:15.473051+00', 'Adds the atomic v5.2 Purchasing V2 supplier-invoice path over posted GRN quantities. It preserves normal v5.1 direct journal + legacy_unverified evidence outside the private transaction context, strengthens bound-source suppression after the atomic source is known, blocks unclassified additional charges, uses the central GST engine as the only tax calculator, preserves supplier invoice legal identity, posts component GST/RCM accounting and supplier payable atomically, and adjusts stock acquisition cost only while linked GRN stock remains unconsumed so historical COGS is never silently rewritten. GRN-linked stock, supplier ledger, PO invoiced quantities, immutable GST snapshot and authoritative journal roll back together on failure.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (244, '5.2.0-foundation', 'GST Compliance Workspace Read APIs', '2026-08-31 13:24:44.682669+00', 'Adds authoritative GST period summaries, evidence browser/detail with journal drill-down, signed return handling and a combined compliance workspace payload. Provider/GSP/IRP submission remains intentionally disabled.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (245, '5.2.0-foundation', 'GST Compliance Readiness and UI Contract', '2026-08-31 13:25:58.787347+00', 'Separates transition evidence coverage from authoritative historical completeness and provider submission readiness, and publishes the permission-aware GST workspace tab/RPC contract. Legacy evidence can no longer be mistaken for filing-ready authoritative evidence.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (246, '5.2.0-foundation', 'GST Evidence Drill-down Fix', '2026-08-31 13:26:50.568197+00', 'Corrects GST evidence journal drill-down to use accounting_accounts.code while preserving authenticated-only access and fixed search path.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (247, '5.2.0-foundation', 'GST Application Cutover Contract', '2026-08-31 13:32:26.717776+00', 'Publishes the explicit Client/POS/Offline POS/Mobile POS v5.2 GST transaction RPC map while preserving the frozen v5.1.0 Build 27 backend contract and legacy behavior. No automatic routing or legacy fallback is changed; applications opt into authoritative v5.2 writers explicitly.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (251, '5.2.0', 'GST Compliance UI Setup Lookups', '2026-08-31 13:55:15.036972+00', 'Read-only, permission-scoped setup lookup API for GST location, product, customer and supplier configuration; UI contract v3.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (252, '5.2.0', 'GST Compliance UI Permission Contract', '2026-08-31 14:06:18.987128+00', 'UI contract v4 separates read permission from registration/product/party write permissions and publishes canonical GST form option enums.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (253, '5.2.0', 'GST Tenant Tax Mode + Non-GST Authoritative Path', '2026-09-01 06:38:17.740384+00', 'Adds explicit effective-dated GST Registered/Non-GST tenant mode; Non-GST transactions stay on v5.2 authoritative writers with zero GST and commercial-invoice evidence; returns inherit original document tax mode; hardens GST registration version table RLS.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (254, '5.2.0', 'Tax-Mode Aware GST Compliance Workspace', '2026-09-01 06:47:15.53587+00', 'Makes GST readiness, workspace, dashboard and UI visibility aware of GST Registered vs Non-GST vs unconfigured mode. Non-GST no longer reports GSTIN/HSN/GSP setup as blockers while retaining authoritative v5.2 transaction evidence.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (255, '6.0.0-build1', 'THQ Transaction Story Foundation', '2026-09-01 21:32:46.503828+00', 'v6.0 Build 1 foundation: Audit Center module and permissions, dedicated auditor role, append-only tamper-evident transaction story, correlation IDs, actor/device/approval snapshots and change-field evidence. Does not alter v5.2 GST/accounting calculation or posting rules.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (256, '6.0.0-build1', 'THQ Transaction Story Capture + History', '2026-09-01 21:34:10.372354+00', 'Captures business-significant inserts/updates/deletes for sales, payments, returns, purchases, inventory, journals, approvals and document origins into the append-only v6.0 transaction story. Adds permission-aware History/Why and hash-chain verification APIs. Existing v5.2 GST/accounting writers are not replaced or rerouted.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (257, '6.0.0-build1', 'Audit Center + Risk Engine', '2026-09-01 21:36:08.195457+00', 'Adds THQ Audit Center backend with High Risk/Needs Review/Normal classification, configurable tenant thresholds, immutable finding evidence, reviewer lifecycle, normal-transaction feed and full evidence drill-down. Risk classification is secondary and cannot rewrite business/accounting records.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (258, '6.0.0-build1', 'Product Profitability + Profit Explanation', '2026-09-01 21:38:21.250472+00', 'Adds deterministic product profitability using sale-item recognized COGS, net revenue before GST and proportional reversal of original sale-item revenue/COGS for returns. Adds exact gross-profit bridge and non-causal diagnostic drivers for cost, selling revenue, discount and return rates. Current product master cost is never used to rewrite historical profit.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (259, '6.0.0-build1', 'Explain This Number Engine', '2026-09-01 21:40:30.139357+00', 'Adds deterministic, ledger-backed explanations for Sales, COGS, Gross Profit, Net Profit, Inventory Value, Receivables, Payables, Cash, Bank and Net GST Payable. Period metrics compare equal-length prior periods; balance metrics compare opening vs ending balances. Source-type driver impacts are quantified and reconciliation status is explicit; product GP drivers are included for gross profit without allowing text to invent numbers.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (260, '6.0.0-build1', 'Explain Balance Scope Hotfix', '2026-09-01 21:41:21.048511+00', 'Corrects v6.0 balance-metric calculations and component details so only posted journal headers within the requested as-of date and location scope contribute. Period Sales/COGS/Profit calculations were already correctly scoped. Also keeps balance-driver change tied to in-period posted movement.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (261, '6.0.0-build1', 'Explain Driver Hardening', '2026-09-01 21:42:32.122698+00', 'Refactors Explain This Number into small deterministic source-driver, balance-component and product-driver helpers. Removes fragile branch logic, makes GST component contribution signs explicit, and preserves exact ledger-first equations and driver reconciliation checks.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (262, '6.0.0-build1', 'GST Story + Why Explanation Contract', '2026-09-01 21:44:45.107005+00', 'Adds v6.0 Transaction Story capture for authoritative GST snapshots and legacy GST evidence without altering v5.2 writers. Adds the reusable Why/History explanation RPC combining v6 events with genuine historical audit, payment, approval, device/origin, permitted journal/stock and GST evidence. Historical gaps are explicitly labeled and never fabricated. The no-legacy-fallback rule for failed v5.2 transactions is preserved.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (263, '6.0.0-build1', 'Audit Historical Bootstrap + Export', '2026-09-01 21:46:43.937325+00', 'Adds controlled permission-gated baseline reconstruction for existing sales, payments, returns, purchases, purchase invoices, supplier payments, journals and stock adjustments. Baselines never infer missing history. Adds audit export with sensitive-evidence redaction and makes every finding review/resolution itself auditable.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (264, '6.0.0-build1', 'Audit Writer Overload Hotfix', '2026-09-01 21:47:31.368248+00', 'Disambiguates v6.0 calls to the overloaded business audit writer by explicitly typing missing before-state as JSONB. The failed bootstrap attempt was transactional and left no partial story events.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (265, '6.0.0-build1', 'History Quality + Return Correlation', '2026-09-01 21:48:58.431808+00', 'Correctly distinguishes native v6 events from reconstructed historical baselines, exposes event-level evidence quality/metadata, and includes sale-return correlation chains (such as return journals/stock movements) in the parent sale Why/History timeline without rewriting existing hash chains.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (266, '6.0.0-build1', 'Historical Risk False-Positive Correction', '2026-09-01 21:51:07.717677+00', 'Prevents reconstructed historical baseline timestamps from triggering backdated sale/journal risk rules. Existing baseline-derived backdate findings are preserved as immutable evidence but system-dismissed with an explicit correction note instead of being deleted. Static factual checks such as negative margin, unusual discount and manual journal remain eligible on historical baselines.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (267, '6.0.0-build1', 'Audit Active-Risk Semantics', '2026-09-01 21:51:52.976856+00', 'Audit Center High Risk and Needs Review cards now count active attention states only. Transactions whose findings are explained/resolved/dismissed return to the Normal feed while their immutable finding evidence remains available in lifecycle history. Summary exposes retained finding lifecycle counts separately.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (268, '6.0.0-build1', 'Audit Center Client Navigation', '2026-09-02 05:58:50.814935+00', 'Adds the Audit Center to the existing server-driven Client Compliance menu, permission-gated by audit_center.view. No financial or GST writer behavior changes.');
INSERT INTO public.thq_schema_releases (migration_no, schema_version, release_name, applied_at, notes) VALUES (269, '6.0.0-build1', 'v6.0 Build 1 App Release Registry', '2026-09-02 06:06:16.032751+00', 'Registers non-mandatory v6.0 Build 1 application releases for Client, POS and Admin. No transaction, GST, inventory or accounting writer behavior changes.');
